const ENVELOPE = [[0.0000, -500.0000], [200.0000, -500.0000], [2490.0000, 0.0000], [2490.0000, 6000.0000], [0.0000, 6000.0000]];

function revolveOutline(context is Context, id is Id, pts is array) returns Query
{
    const sk = newSketchOnPlane(context, id + "sk", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    var p = [];
    for (var q in pts)
        p = append(p, vector(q[0], q[1]) * millimeter);
    p = append(p, p[0]);
    skPolyline(sk, "outline", { "points" : p });
    skSolve(sk);
    opRevolve(context, id + "rev", { "entities" : qSketchRegion(id + "sk"), "axis" : line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)),
                "angleForward" : 2 * PI * radian });
    opDeleteBodies(context, id + "del", { "entities" : qCreatedBy(id + "sk") });
    return qCreatedBy(id + "rev", EntityType.BODY);
}

function tag(context is Context, bodies is Query, name is string, mat, col is Color)
{
    setProperty(context, { "entities" : bodies, "propertyType" : PropertyType.NAME, "value" : name });
    if (mat != undefined)
        setProperty(context, { "entities" : bodies, "propertyType" : PropertyType.MATERIAL, "value" : mat });
    setProperty(context, { "entities" : bodies, "propertyType" : PropertyType.APPEARANCE, "value" : col });
}

function shell(context is Context, id is Id, zc is number, ri is number, ro is number, name is string, mat, col is Color)
{
    opSphere(context, id + "outer", { "center" : vector(0, 0, zc) * millimeter, "radius" : ro * millimeter });
    opSphere(context, id + "inner", { "center" : vector(0, 0, zc) * millimeter, "radius" : ri * millimeter });
    opBoolean(context, id + "hollow", { "tools" : qCreatedBy(id + "inner", EntityType.BODY), "targets" : qCreatedBy(id + "outer", EntityType.BODY),
                "operationType" : BooleanOperationType.SUBTRACTION });
    tag(context, qCreatedBy(id + "outer", EntityType.BODY), name, mat, col);
}

annotation { "Feature Type Name" : "ABEONA engine and tanks" }
export const abeonaBuild = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        // 1. Engine
        tag(context, revolveOutline(context, id + "liner", LINER), "Engine - Ablative liner (silica phenolic)",
            material("Silica phenolic", 1750.0 * kilogram / meter ^ 3), color(0.45, 0.35, 0.3));
        tag(context, revolveOutline(context, id + "case", CASE), "Engine - Chamber case (Ti-6Al-4V)",
            material("Ti-6Al-4V", 4430.0 * kilogram / meter ^ 3), color(0.7, 0.7, 0.75));
        tag(context, revolveOutline(context, id + "ext", EXTENSION), "Engine - Nozzle extension (C-103)",
            material("C-103 niobium", 8860.0 * kilogram / meter ^ 3), color(0.35, 0.35, 0.4));
        fCylinder(context, id + "plate", { "bottomCenter" : vector(0, 0, 275.9823) * millimeter, "topCenter" : vector(0, 0, 295.9823) * millimeter,
                    "radius" : 121.4091 * millimeter });
        fCylinder(context, id + "head", { "bottomCenter" : vector(0, 0, 295.9823) * millimeter, "topCenter" : vector(0, 0, 625.9823) * millimeter,
                    "radius" : 121.4091 * millimeter });
        var cavs = [];
        for (var i = 0; i < 12; i += 1)
        {
            const a = (15 + 360 * i / 12) * degree;
            fCylinder(context, id + ("cav" ~ i), { "bottomCenter" : vector(100.0 * cos(a), 100.0 * sin(a), 275.9823) * millimeter,
                        "topCenter" : vector(100.0 * cos(a), 100.0 * sin(a), 335.3437) * millimeter,
                        "radius" : 8.0 * millimeter });
            cavs = append(cavs, qCreatedBy(id + ("cav" ~ i), EntityType.BODY));
        }
        opBoolean(context, id + "cavities", { "tools" : qUnion(cavs),
                    "targets" : qUnion([qCreatedBy(id + "plate", EntityType.BODY), qCreatedBy(id + "head", EntityType.BODY)]),
                    "operationType" : BooleanOperationType.SUBTRACTION });
        tag(context, qCreatedBy(id + "plate", EntityType.BODY), "Engine - Injector plate (304L, 12 acoustic cavities)",
            material("304L stainless", 7900.0 * kilogram / meter ^ 3), color(0.8, 0.8, 0.82));
        tag(context, qCreatedBy(id + "head", EntityType.BODY), "Engine - Head/valve/gimbal stack (lumped 44 kg)",
            material("Lumped head stack", 2897.301 * kilogram / meter ^ 3), color(0.55, 0.55, 0.6));

        // 2. Tanks
        shell(context, id + "tankNTO", 1943.4892, 1317.5069, 1319.6716, "Tank - NTO (Ti-6Al-4V)", material("Ti-6Al-4V", 4430.0 * kilogram / meter ^ 3), color(0.85, 0.45, 0.2));
        shell(context, id + "tankMMH", 4677.3613, 1316.3652, 1318.5280, "Tank - MMH (Ti-6Al-4V)", material("Ti-6Al-4V", 4430.0 * kilogram / meter ^ 3), color(0.3, 0.6, 0.85));
        for (var i = 0; i < 4; i += 1)
        {
            const ang = [45, 135, 225, 315][i];
            const a = ang * degree;
            opSphere(context, id + ("copv" ~ i), { "center" : vector(1961.2614 * cos(a), 1961.2614 * sin(a), 3310.9961) * millimeter,
                        "radius" : 478.7386 * millimeter });
            tag(context, qCreatedBy(id + ("copv" ~ i), EntityType.BODY), "COPV - He " ~ (i + 1) ~ " (" ~ ang ~ " deg, lumped 95.0 kg)",
                material("Lumped COPV", 206.6667 * kilogram / meter ^ 3), color(0.2, 0.2, 0.2));
        }

        // 3. Envelope (reference only, no material)
        tag(context, revolveOutline(context, id + "env", ENVELOPE), "REF - Service module envelope", undefined, color(0.6, 0.75, 0.95, 0.15));
    });
